import re
import ipaddress
import socket
import urllib.parse
from typing import Optional, Tuple
import unicodedata
import aiohttp
from aiohttp import web


class SSRFProtector:
    """Enterprise-grade SSRF protection with comprehensive URL validation."""

    BLOCKED_RANGES = [
        ipaddress.ip_network('127.0.0.0/8'),
        ipaddress.ip_network('10.0.0.0/8'),
        ipaddress.ip_network('172.16.0.0/12'),
        ipaddress.ip_network('192.168.0.0/16'),
        ipaddress.ip_network('169.254.0.0/16'),
        ipaddress.ip_network('::1/128'),
        ipaddress.ip_network('fc00::/7'),
        ipaddress.ip_network('fe80::/10'),
    ]

    ALLOWED_SCHEMES = ('http', 'https')
    MAX_URL_LENGTH = 2048
    MAX_REDIRECTS = 5

    # Strict hostname pattern - only ASCII alphanumeric, hyphens, dots
    HOSTNAME_RE = re.compile(r'^[a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?)*$')

    @classmethod
    def _is_ip_blocked(cls, ip_str: str) -> bool:
        """Check if an IP address falls within blocked ranges."""
        try:
            addr = ipaddress.ip_address(ip_str)
            return any(addr in network for network in cls.BLOCKED_RANGES)
        except ValueError:
            return True  # If we can't parse it, block it

    @classmethod
    def _resolve_and_check(cls, hostname: str) -> bool:
        """Resolve hostname and verify all IPs are safe."""
        try:
            # Resolve all addresses
            results = socket.getaddrinfo(hostname, None, socket.AF_UNSPEC)
            if not results:
                return False
            for family, _, _, _, sockaddr in results:
                ip = sockaddr[0]
                if cls._is_ip_blocked(ip):
                    return False
            return True
        except (socket.gaierror, socket.herror, OSError):
            return False

    @classmethod
    def validate_url(cls, url: str) -> Tuple[bool, Optional[str]]:
        """Validate URL against SSRF attacks.

        Security: We validate the raw URL as-provided to ensure what we check
        is exactly what will be fetched. No transformations applied.
        """
        if not url or len(url) > cls.MAX_URL_LENGTH:
            return False, "URL empty or too long"

        # Block obviously malicious characters
        if any(c in url for c in ['\r', '\n', '\t', '\x00']):
            return False, "URL contains control characters"

        parsed = urllib.parse.urlparse(url)

        # Scheme validation
        if parsed.scheme.lower() not in cls.ALLOWED_SCHEMES:
            return False, f"Scheme '{parsed.scheme}' not allowed"

        # Must have a hostname
        hostname = parsed.hostname
        if not hostname:
            return False, "No hostname found"

        # Block credentials in URL
        if parsed.username or parsed.password:
            return False, "Credentials in URL not allowed"

        # Check if hostname is an IP address directly
        try:
            if cls._is_ip_blocked(hostname):
                return False, "IP address is in blocked range"
            # It's a valid IP, and it's not blocked
            return True, None
        except ValueError:
            pass  # Not an IP, continue with hostname validation

        # Validate hostname format
        if not cls.HOSTNAME_RE.match(hostname):
            return False, "Invalid hostname format"

        # DNS resolution check
        if not cls._resolve_and_check(hostname):
            return False, "Hostname resolves to blocked IP"

        return True, None


class WebhookService:
    """Service for sending webhooks to user-configured URLs."""

    def __init__(self):
        self.protector = SSRFProtector()
        self.session: Optional[aiohttp.ClientSession] = None

    async def get_session(self) -> aiohttp.ClientSession:
        if self.session is None or self.session.closed:
            # Trust the system's DNS resolver, disable auto-redirect
            # to validate each hop
            self.session = aiohttp.ClientSession(
                timeout=aiohttp.ClientTimeout(total=10),
                connector=aiohttp.TCPConnector(
                    ssl=True,
                    limit=100,
                    ttl_dns_cache=300,
                ),
            )
        return self.session

    def _prepare_url(self, raw_url: str) -> str:
        """Prepare URL for fetching. Apply NFKC normalization for 
        internationalized domain names (IDN) compatibility.

        This ensures consistent handling of Unicode in URLs per RFC 3987.
        """
        # Normalize Unicode for consistent IDN handling
        normalized = unicodedata.normalize('NFKC', raw_url)
        return normalized

    async def send_webhook(self, url: str, payload: dict) -> dict:
        """Send webhook to the specified URL with SSRF protection."""

        # Step 1: Validate the URL
        is_valid, error = self.protector.validate_url(url)
        if not is_valid:
            return {'success': False, 'error': f'URL validation failed: {error}'}

        # Step 2: Prepare URL for fetching (IDN normalization)
        fetch_url = self._prepare_url(url)

        # Step 3: Fetch with redirect validation
        session = await self.get_session()
        redirects = 0
        current_url = fetch_url

        try:
            while redirects <= SSRFProtector.MAX_REDIRECTS:
                async with session.post(
                    current_url,
                    json=payload,
                    allow_redirects=False,
                ) as resp:
                    if resp.status in (301, 302, 303, 307, 308):
                        redirects += 1
                        location = resp.headers.get('Location', '')
                        # Validate redirect target
                        redirect_url = urllib.parse.urljoin(current_url, location)
                        is_valid, error = self.protector.validate_url(redirect_url)
                        if not is_valid:
                            return {'success': False, 'error': f'Redirect blocked: {error}'}
                        current_url = self._prepare_url(redirect_url)
                    else:
                        return {
                            'success': True,
                            'status': resp.status,
                            'body': await resp.text()
                        }

            return {'success': False, 'error': 'Too many redirects'}
        except Exception as e:
            return {'success': False, 'error': str(e)}


# Application setup
app = web.Application()
webhook_service = WebhookService()


async def handle_webhook(request: web.Request) -> web.Response:
    """Handle webhook registration and sending."""
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'error': 'Invalid JSON'}, status=400)

    url = data.get('url')
    payload = data.get('payload', {})

    if not isinstance(url, str):
        return web.json_response({'error': 'URL must be a string'}, status=400)
    if not isinstance(payload, dict):
        return web.json_response({'error': 'Payload must be an object'}, status=400)

    result = await webhook_service.send_webhook(url, payload)
    status = 200 if result.get('success') else 403
    return web.json_response(result, status=status)


app.router.add_post('/api/webhook/send', handle_webhook)

if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=8080)
